"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { useMemo } from "react"

import { FieldGroup } from "@/components/ui/field"
import {
  type Facility,
  type Program,
  type RightType,
  type Role,
  type RoleAssignment,
  rightLabel,
  roleTypeOf,
  type SupervisoryNode,
} from "@/components/openlmis/user-roles-page/role-assignments"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { Callout } from "@/components/openlmis/callout"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  ComboboxField,
  FieldSkeleton,
} from "@/components/openlmis/form-fields/form-fields"

import {
  EMPTY_ROLE_FORM,
  type RoleFormValues,
  roleFormSchema,
  toRoleAssignment,
} from "@/components/openlmis/user-roles-page/role-form"

const TYPE_LABEL: Record<RightType, string> = {
  SUPERVISION: "Supervision",
  ORDER_FULFILLMENT: "Fulfillment",
  REPORTS: "Reports",
  GENERAL_ADMIN: "Administration",
}

/** The dialog's choices; a list left undefined shows a skeleton in its field. */
export type AddRoleOptions = {
  roles: readonly Role[] | undefined
  programs: readonly Program[] | undefined
  nodes: readonly SupervisoryNode[] | undefined
  facilities: readonly Facility[] | undefined
}

type AddRoleDialogProps = AddRoleOptions & {
  /** The type of role being added; the dialog is open while it is set. */
  type: RightType | undefined
  /** The roles the user holds now, so the same one cannot be added twice. */
  assigned: readonly RoleAssignment[]
  username: string
  hasHomeFacility: boolean
  onAdd: (assignment: RoleAssignment) => void
  onClose: () => void
}

export function AddRoleDialog({ type, onClose, ...props }: AddRoleDialogProps) {
  const { shown, dialogProps } = useDialogTarget(type, onClose)

  return (
    <FormDialog {...dialogProps()}>
      {shown && (
        <AddRoleContent key={shown} onDone={onClose} type={shown} {...props} />
      )}
    </FormDialog>
  )
}

type ContentProps = Omit<AddRoleDialogProps, "type" | "onClose"> & {
  type: RightType
  onDone: () => void
}

const byName = <T extends { name: string }>(a: T, b: T) =>
  a.name.localeCompare(b.name)

function AddRoleContent({ roles, ...props }: ContentProps) {
  const { type, username } = props
  const ofType = useMemo(
    () =>
      // oxlint-disable-next-line unicorn/no-array-sort -- sorts the fresh filtered array
      roles?.filter((role) => roleTypeOf(role) === type).sort(byName),
    [roles, type]
  )

  if (!ofType) {
    return (
      <>
        <AddRoleHeader type={type} username={username} />
        <FormDialogBody>
          <div aria-busy>
            <FieldGroup>
              {type === "SUPERVISION" && (
                <FieldSkeleton label="Program" required />
              )}
              <FieldSkeleton label="Role" required />
            </FieldGroup>
          </div>
        </FormDialogBody>
        <FormDialogFooter>
          <FormDialogCancel />
          <FormDialogSubmit disabled>Add Role</FormDialogSubmit>
        </FormDialogFooter>
      </>
    )
  }
  return <AddRoleForm {...props} roles={ofType} />
}

function AddRoleHeader({
  type,
  username,
}: {
  type: RightType
  username: string
}) {
  return (
    <FormDialogHeader>
      <FormDialogTitle>Add {TYPE_LABEL[type]} Role</FormDialogTitle>
      <FormDialogDescription>
        Choose a {TYPE_LABEL[type].toLowerCase()} role to grant to {username}.
      </FormDialogDescription>
    </FormDialogHeader>
  )
}

function AddRoleForm({
  type,
  roles,
  assigned,
  username,
  hasHomeFacility,
  onAdd,
  onDone,
  programs,
  nodes,
  facilities,
}: Omit<ContentProps, "roles"> & { roles: Role[] }) {
  const schema = useMemo(() => roleFormSchema(type, assigned), [type, assigned])

  const form = useAppForm({
    // A type with a single role has nothing to choose, so it starts chosen.
    defaultValues: {
      ...EMPTY_ROLE_FORM,
      roleId: roles.length === 1 ? (roles[0]?.id ?? null) : null,
    } satisfies RoleFormValues,
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => {
      onAdd(toRoleAssignment(type, value))
      onDone()
    },
  })

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <AddRoleHeader type={type} username={username} />
      <FormDialogBody>
        <FieldGroup>
          {type === "SUPERVISION" && (
            <>
              <form.AppField name="programId">
                {() => <ProgramField programs={programs} />}
              </form.AppField>
              <form.AppField name="supervisoryNodeId">
                {() => <NodeField facilities={facilities} nodes={nodes} />}
              </form.AppField>
            </>
          )}
          {type === "ORDER_FULFILLMENT" && (
            <form.AppField name="warehouseId">
              {() => <FacilityField facilities={facilities} />}
            </form.AppField>
          )}
          <form.AppField name="roleId">
            {(field) => <RoleField roleId={field.state.value} roles={roles} />}
          </form.AppField>
          {type === "SUPERVISION" && !hasHomeFacility && (
            <form.Subscribe
              selector={(state) => state.values.supervisoryNodeId}
            >
              {(nodeId) =>
                !nodeId && (
                  <Callout title="No Home Facility" tone="warning">
                    Without a supervisory node this role applies at the home
                    facility, and {username} has none, so it grants nothing
                    until one is set.
                  </Callout>
                )
              }
            </form.Subscribe>
          )}
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <FormDialogSubmit>Add Role</FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

/** Hints how many there are, since the list shows the first 50 until the user types. */
const searchHint = (count: number, noun: string) =>
  `Type to search ${count} ${noun}.`

function ProgramField({ programs }: Pick<AddRoleOptions, "programs">) {
  const items = useMemo(() => {
    const sorted = [...(programs ?? [])]
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts a copy
    sorted.sort(byName)
    return sorted.map((program) => ({ value: program.id, label: program.name }))
  }, [programs])
  if (!programs) return <FieldSkeleton label="Program" required />
  return (
    <ComboboxField
      clearLabel="Clear Program"
      emptyMessage="No programs found."
      items={items}
      label="Program"
      placeholder="Search Programs..."
      required
    />
  )
}

/** Each node with its facility, as OpenLMIS names them, e.g. "FP Approval Point (Balaka)". */
function NodeField({
  nodes,
  facilities,
}: Pick<AddRoleOptions, "nodes" | "facilities">) {
  const items = useMemo(() => {
    const names = new Map(
      (facilities ?? []).map((facility) => [facility.id, facility.name])
    )
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts a copy
    return [...(nodes ?? [])].sort(byName).map((node) => {
      const facility = node.facility && names.get(node.facility.id)
      return {
        value: node.id,
        label: facility ? `${node.name} (${facility})` : node.name,
      }
    })
  }, [nodes, facilities])

  if (!nodes || !facilities) return <FieldSkeleton label="Supervisory Node" />
  return (
    <ComboboxField
      clearLabel="Clear Supervisory Node"
      description={`${searchHint(items.length, "nodes")} Leave empty for the home facility.`}
      emptyMessage="No supervisory nodes found."
      items={items}
      label="Supervisory Node"
      placeholder="Search Supervisory Nodes..."
    />
  )
}

function FacilityField({ facilities }: Pick<AddRoleOptions, "facilities">) {
  const items = useMemo(
    () =>
      // oxlint-disable-next-line unicorn/no-array-sort -- sorts a copy
      [...(facilities ?? [])].sort(byName).map((facility) => ({
        value: facility.id,
        label: `${facility.code} - ${facility.name}`,
      })),
    [facilities]
  )
  if (!facilities) return <FieldSkeleton label="Facility" required />
  return (
    <ComboboxField
      clearLabel="Clear Facility"
      description={searchHint(items.length, "facilities")}
      emptyMessage="No facilities found."
      items={items}
      label="Facility"
      placeholder="Search Facilities..."
      required
    />
  )
}

/** The roles of this type; once one is picked, the rights it grants show beneath. */
function RoleField({
  roles,
  roleId,
}: {
  roles: Role[]
  roleId: string | null
}) {
  const items = useMemo(
    () => roles.map((role) => ({ value: role.id, label: role.name })),
    [roles]
  )
  const labels = roles
    .find((role) => role.id === roleId)
    ?.rights.map((right) => rightLabel(right.name))
  // oxlint-disable-next-line unicorn/no-array-sort -- sorts the fresh mapped array
  const rights = labels?.sort().join(", ")

  return (
    <ComboboxField
      clearLabel="Clear Role"
      description={rights && `Grants ${rights}.`}
      emptyMessage="No roles found."
      items={items}
      label="Role"
      placeholder="Search Roles..."
      required
    />
  )
}

import { z } from "zod"

import {
  assignmentKey,
  type RightType,
  type RoleAssignment,
  toSavedAssignment,
} from "@/components/openlmis/user-roles-page/role-assignments"

const roleFormFields = z.object({
  roleId: z.string().nullable(),
  programId: z.string().nullable(),
  supervisoryNodeId: z.string().nullable(),
  warehouseId: z.string().nullable(),
})

export type RoleFormValues = z.input<typeof roleFormFields>

export const EMPTY_ROLE_FORM: RoleFormValues = {
  roleId: null,
  programId: null,
  supervisoryNodeId: null,
  warehouseId: null,
}

/** The assignment the form describes, with only the ids its type uses. */
export function toRoleAssignment(
  type: RightType,
  values: RoleFormValues
): RoleAssignment {
  return toSavedAssignment({
    roleId: values.roleId ?? "",
    ...(type === "SUPERVISION" && {
      programId: values.programId,
      supervisoryNodeId: values.supervisoryNodeId,
    }),
    ...(type === "ORDER_FULFILLMENT" && { warehouseId: values.warehouseId }),
  })
}

/** Each type needs its own fields; the same role twice, in the same place, is refused. */
export function roleFormSchema(
  type: RightType,
  assigned: readonly RoleAssignment[]
) {
  const assignedKeys = new Set(assigned.map(assignmentKey))

  return roleFormFields.superRefine((values, context) => {
    const require = (path: keyof RoleFormValues, message: string) => {
      if (!values[path])
        context.addIssue({ code: "custom", path: [path], message })
    }
    if (type === "SUPERVISION") require("programId", "Choose a program.")
    if (type === "ORDER_FULFILLMENT")
      require("warehouseId", "Choose a facility.")
    require("roleId", "Choose a role.")

    if (
      values.roleId &&
      assignedKeys.has(assignmentKey(toRoleAssignment(type, values)))
    ) {
      context.addIssue({
        code: "custom",
        path: ["roleId"],
        message: "This user already has this role here.",
      })
    }
  })
}

"use client"

import { revalidateLogic, useStore } from "@tanstack/react-form"
import { useMemo } from "react"
import { z } from "zod"

import { FieldDescription, FieldGroup } from "@/components/ui/field"
import {
  mergeAssignments,
  type RoleAssignment,
} from "@/components/openlmis/user-roles-page/role-assignments"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  ComboboxField,
  FieldSkeleton,
} from "@/components/openlmis/form-fields/form-fields"

export type ImportSourceUser = {
  id: string
  username: string
  firstName?: string | null
  lastName?: string | null
  roleAssignments: RoleAssignment[]
}

const importSchema = z.object({
  userId: z
    .string()
    .nullable()
    .refine(Boolean, "Choose a user to copy roles from."),
})

type ImportRolesDialogProps = {
  open: boolean
  /** The user being edited, left out of the list. */
  userId: string
  username: string
  /** The roles being edited now, to count which ones are new. */
  draft: readonly RoleAssignment[]
  /** Who roles can be copied from; the field shows a skeleton until it is set. */
  users: readonly ImportSourceUser[] | undefined
  onImport: (assignments: RoleAssignment[], fromUsername: string) => void
  onClose: () => void
}

/** Copies another user's roles into the draft; nothing is saved until the page is. */
export function ImportRolesDialog({
  open,
  onClose,
  ...props
}: ImportRolesDialogProps) {
  const { shown, dialogProps } = useDialogTarget(open || undefined, onClose)
  return (
    <FormDialog {...dialogProps()}>
      {shown && <ImportRolesForm onDone={onClose} {...props} />}
    </FormDialog>
  )
}

function ImportRolesForm({
  userId,
  username,
  draft,
  users,
  onImport,
  onDone,
}: Omit<ImportRolesDialogProps, "open" | "onClose"> & { onDone: () => void }) {
  const form = useAppForm({
    defaultValues: { userId: null as string | null },
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: importSchema },
    onSubmit: ({ value }) => {
      const from = users?.find((user) => user.id === value.userId)
      if (!from) return
      onImport(from.roleAssignments, from.username)
      onDone()
    },
  })
  const sourceId = useStore(form.store, (state) => state.values.userId)
  const source = users?.find((user) => user.id === sourceId)

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <FormDialogHeader>
        <FormDialogTitle>Import Roles</FormDialogTitle>
        <FormDialogDescription>
          Copy another user's roles to {username}. They are added to the roles
          on this page and saved with them.
        </FormDialogDescription>
      </FormDialogHeader>
      <FormDialogBody>
        <FieldGroup>
          <form.AppField name="userId">
            {() =>
              users ? (
                <UserField excludeId={userId} users={users} />
              ) : (
                <FieldSkeleton label="User" required />
              )
            }
          </form.AppField>
          {source && (
            <ImportPreview draft={draft} roles={source.roleAssignments} />
          )}
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <FormDialogSubmit>Import Roles</FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

/** Reads its field from the surrounding `AppField`. */
function UserField({
  users,
  excludeId,
}: {
  users: readonly ImportSourceUser[]
  excludeId: string
}) {
  const items = useMemo(
    () =>
      users
        .filter((user) => user.id !== excludeId)
        .map((user) => {
          const name = [user.firstName, user.lastName].filter(Boolean).join(" ")
          return {
            value: user.id,
            label: name ? `${user.username} (${name})` : user.username,
          }
        }),
    [users, excludeId]
  )
  return (
    <ComboboxField
      clearLabel="Clear User"
      description={`Type to search ${items.length} users.`}
      emptyMessage="No users found."
      items={items}
      label="User"
      placeholder="Search Users..."
      required
    />
  )
}

const count = (n: number) => (n === 1 ? "1 role" : `${n} roles`)

/** How many of the chosen user's roles are new here, before anything is added. */
function ImportPreview({
  draft,
  roles,
}: {
  draft: readonly RoleAssignment[]
  roles: readonly RoleAssignment[]
}) {
  const { added, skipped } = mergeAssignments(draft, roles)
  return (
    <FieldDescription>
      {added === 0
        ? "They have no roles this user does not already have."
        : skipped === 0
          ? `Adds ${count(added)}.`
          : `Adds ${count(added)}; ${count(skipped)} this user already has.`}
    </FieldDescription>
  )
}

"use client"

import {
  createColumnHelper,
  functionalUpdate,
  type PaginationState,
  type SortingState,
  useTable,
} from "@tanstack/react-table"
import {
  EllipsisIcon,
  PlusIcon,
  SearchXIcon,
  ShieldIcon,
  Trash2Icon,
} from "lucide-react"
import { useMemo, useState } from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Skeleton } from "@/components/ui/skeleton"
import {
  DataTable,
  DataTableColumnHeader,
  DataTableEmpty,
  DataTableError,
  type DataTableFeatures,
  DataTablePagination,
  DataTableSkeleton,
  dataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import { useContainerSize } from "@/components/blocks/openlmis/data-table/responsive-columns"
import { SearchInput } from "@/components/openlmis/search-input/search-input"
import { StatusBadge } from "@/components/openlmis/status-badge"

import {
  compareRows,
  filterRows,
  type RoleRow,
  type RoleSortField,
  type RoleTab,
} from "@/components/openlmis/user-roles-page/role-assignments"
import { RoleRightsPopover } from "@/components/openlmis/user-roles-page/role-rights-popover"

/** Whether the node and facility names have arrived; they load after the rows, and may fail. */
export type LookupStatus = {
  nodes: "pending" | "ready" | "failed"
  facilities: "pending" | "ready" | "failed"
}

type NameStatus = LookupStatus["nodes"]

const EMPTY_TEXT: Record<RoleTab["id"], string> = {
  supervision:
    "Supervision roles let this user work on a program's requisitions, at a supervisory node or at their home facility.",
  fulfillment: "Fulfillment roles let this user handle orders at a facility.",
  reports: "Reports roles let this user see reports.",
  administration: "Administration roles let this user manage the system.",
}

const columnHelper = createColumnHelper<DataTableFeatures, RoleRow>()

/** A name; a placeholder while it loads, a dash if its lookup failed, "Unknown" if it is gone. */
function Name({
  value,
  status = "ready",
}: {
  value: string | undefined
  status?: NameStatus
}) {
  if (value !== undefined) return <span className="truncate">{value}</span>
  if (status === "pending") return <Skeleton className="h-4 w-2/3" />
  if (status === "failed")
    return <span className="text-muted-foreground">-</span>
  return <span className="text-muted-foreground">Unknown</span>
}

/** The node with its facility beneath, or Home Facility with the user's home facility. */
function NodeCell({ row, status }: { row: RoleRow; status: LookupStatus }) {
  const facilityPending =
    status.facilities === "pending" ||
    (!row.isHomeFacility && status.nodes === "pending")
  return (
    <span className="flex min-w-0 flex-col">
      {row.isHomeFacility ? (
        <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
          <span className="truncate">Home Facility</span>
          {row.isIgnored && <StatusBadge tone="warning">Ignored</StatusBadge>}
        </span>
      ) : (
        <Name status={status.nodes} value={row.node} />
      )}
      {row.isIgnored ? null : row.nodeFacility !== undefined ? (
        <span className="truncate text-xs text-muted-foreground">
          {row.nodeFacility}
        </span>
      ) : (
        facilityPending && <Skeleton className="mt-1 h-3 w-1/2" />
      )}
    </span>
  )
}

type ColumnOptions = {
  tab: RoleTab
  /** Too narrow for a column each, so the role cell carries the rest on lines of its own. */
  compact: boolean
  status: LookupStatus
  /** Left out where the roles are only shown, e.g. on the user's own profile. */
  onRemove?: ((row: RoleRow) => void) | undefined
}

function RoleCell({ row, options }: { row: RoleRow; options: ColumnOptions }) {
  const { tab, compact, status } = options
  return (
    <span className="flex min-w-0 flex-col gap-1">
      <span className="flex min-w-0 items-center gap-2">
        {row.role === undefined ? (
          <Name value={undefined} />
        ) : (
          <RoleRightsPopover
            description={row.description}
            name={row.role}
            rights={row.rights}
          />
        )}
        {row.isUnsaved && <StatusBadge tone="info">Unsaved</StatusBadge>}
      </span>
      {compact && tab.type === "SUPERVISION" && (
        <span className="flex min-w-0 flex-col text-xs text-muted-foreground">
          <Name value={row.program} />
          <NodeCell row={row} status={status} />
        </span>
      )}
      {compact && tab.type === "ORDER_FULFILLMENT" && (
        <span className="text-xs text-muted-foreground">
          <Name status={status.facilities} value={row.facility} />
        </span>
      )}
    </span>
  )
}

function createColumns(options: ColumnOptions) {
  const { tab, compact, status, onRemove } = options
  const role = columnHelper.accessor("role", {
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Role" />
    ),
    cell: ({ row }) => <RoleCell options={options} row={row.original} />,
  })
  const withActions = onRemove
    ? [
        columnHelper.display({
          id: "actions",
          header: () => <span className="sr-only">Actions</span>,
          meta: { className: "w-16" },
          cell: ({ row }) => (
            <RoleActions
              onRemove={() => onRemove(row.original)}
              role={row.original.role ?? "Unknown"}
            />
          ),
        }),
      ]
    : []

  if (compact) return columnHelper.columns([role, ...withActions])

  if (tab.type === "SUPERVISION") {
    return columnHelper.columns([
      columnHelper.accessor("program", {
        header: ({ column }) => (
          <DataTableColumnHeader column={column} title="Program" />
        ),
        meta: { className: "w-1/5" },
        cell: ({ getValue }) => <Name value={getValue()} />,
      }),
      columnHelper.accessor("node", {
        header: ({ column }) => (
          <DataTableColumnHeader column={column} title="Supervisory Node" />
        ),
        meta: { className: "w-2/5" },
        cell: ({ row }) => <NodeCell row={row.original} status={status} />,
      }),
      role,
      ...withActions,
    ])
  }
  if (tab.type === "ORDER_FULFILLMENT") {
    return columnHelper.columns([
      columnHelper.accessor("facility", {
        header: ({ column }) => (
          <DataTableColumnHeader column={column} title="Supplying Facility" />
        ),
        meta: { className: "w-1/2" },
        cell: ({ getValue }) => (
          <Name status={status.facilities} value={getValue()} />
        ),
      }),
      role,
      ...withActions,
    ])
  }
  return columnHelper.columns([role, ...withActions])
}

function RoleActions({
  role,
  onRemove,
}: {
  role: string
  onRemove: () => void
}) {
  return (
    <div className="flex justify-end">
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label={`Actions for ${role}`}
              size="icon-sm"
              variant="ghost"
            />
          }
        >
          <EllipsisIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-auto">
          <DropdownMenuItem onClick={onRemove} variant="destructive">
            <Trash2Icon />
            Remove
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  )
}

type RoleAssignmentsTableProps = Omit<ColumnOptions, "compact"> & {
  /** Every row of the tab, unfiltered; a skeleton shows until it is set. Key the table by tab to reset it. */
  rows: RoleRow[] | undefined
  /** The rows could not be loaded; shows an error with Try Again. */
  failed?: boolean
  onRetry?: () => void
  /** Left out where the roles are only shown; hides Add Role. */
  onAdd?: () => void
}

const INITIAL_SORTING: SortingState = [{ id: "role", desc: false }]
const INITIAL_PAGINATION: PaginationState = { pageIndex: 0, pageSize: 10 }

/** One tab's roles: a search and Add Role above a table that filters, sorts and pages them in the browser. */
export function RoleAssignmentsTable({
  rows,
  failed = false,
  onRetry,
  onAdd,
  ...options
}: RoleAssignmentsTableProps) {
  const [query, setQuery] = useState("")
  const [sorting, setSorting] = useState(INITIAL_SORTING)
  const [pagination, setPagination] = useState(INITIAL_PAGINATION)
  const [measure, size] = useContainerSize<HTMLDivElement>()
  // Below `xl` there is no room for a column per name.
  const compact =
    size === "none" || size === "sm" || size === "md" || size === "lg"

  const { tab, status, onRemove } = options
  const columns = useMemo(
    () => createColumns({ tab, compact, status, onRemove }),
    [tab, compact, status, onRemove]
  )

  const [sort = INITIAL_SORTING[0]] = sorting
  const matching = useMemo(() => {
    const filtered = filterRows(rows ?? [], query)
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts the fresh filtered array
    return filtered.sort(
      compareRows((sort?.id ?? "role") as RoleSortField, sort?.desc ?? false)
    )
  }, [rows, query, sort])
  // A removal can leave the page past the end, so it is held to the last page that exists.
  const lastPage = Math.max(
    0,
    Math.ceil(matching.length / pagination.pageSize) - 1
  )
  // Memoized: the table compares controlled state by reference and would reset it every render.
  const page = useMemo(
    () => ({
      ...pagination,
      pageIndex: Math.min(pagination.pageIndex, lastPage),
    }),
    [pagination, lastPage]
  )
  const data = useMemo(
    () =>
      matching.slice(
        page.pageIndex * page.pageSize,
        (page.pageIndex + 1) * page.pageSize
      ),
    [matching, page.pageIndex, page.pageSize]
  )

  const table = useTable({
    features: dataTableFeatures,
    columns,
    data,
    getRowId: (row) => row.id,
    rowCount: matching.length,
    manualPagination: true,
    manualSorting: true,
    enableSortingRemoval: false,
    state: { sorting, pagination: page },
    onSortingChange: (updater) => {
      setSorting(functionalUpdate(updater, sorting))
      setPagination((current) => ({ ...current, pageIndex: 0 }))
    },
    onPaginationChange: (updater) =>
      setPagination(functionalUpdate(updater, page)),
  })

  const clearSearch = () => {
    setQuery("")
    setPagination((current) => ({ ...current, pageIndex: 0 }))
  }

  return (
    <div className="@container/roles flex flex-col gap-4" ref={measure}>
      <div className="flex flex-wrap items-center gap-2">
        <div className="min-w-0 flex-1 @xl/roles:w-72 @xl/roles:flex-none">
          <SearchInput
            label="Search roles, programs, nodes and facilities"
            onValueChange={(value) => {
              setQuery(value)
              setPagination((current) => ({ ...current, pageIndex: 0 }))
            }}
            placeholder="Search roles..."
            value={query}
          />
        </div>
        {onAdd && (
          <Button className="ms-auto" onClick={onAdd}>
            <PlusIcon data-icon="inline-start" />
            Add Role
          </Button>
        )}
      </div>
      {failed && onRetry ? (
        <DataTableError
          description="Check your connection and try again."
          onRetry={onRetry}
          title="Could Not Load Roles"
        />
      ) : rows === undefined ? (
        <DataTableSkeleton rowCount={5} table={table} />
      ) : (
        <DataTable
          empty={
            rows.length === 0 ? (
              <DataTableEmpty
                action={
                  onAdd && (
                    <Button onClick={onAdd} variant="outline">
                      <PlusIcon data-icon="inline-start" />
                      Add Role
                    </Button>
                  )
                }
                description={
                  onAdd
                    ? EMPTY_TEXT[tab.id]
                    : "Ask an administrator if you need a role of this type."
                }
                icon={<ShieldIcon />}
                title="No Roles Yet"
              />
            ) : (
              <DataTableEmpty
                action={
                  <Button onClick={clearSearch} variant="destructive">
                    Clear Search
                  </Button>
                }
                description="Try a different search."
                icon={<SearchXIcon />}
                title="No Matching Roles"
              />
            )
          }
          footer={matching.length > 0 && <DataTablePagination table={table} />}
          table={table}
        />
      )}
    </div>
  )
}

/** What a right is about; a role's rights all share one type, which is the role's type. */
export type RightType =
  | "SUPERVISION"
  | "ORDER_FULFILLMENT"
  | "REPORTS"
  | "GENERAL_ADMIN"

export type Right = {
  name: string
  type: RightType
}

export type Role = {
  id: string
  name: string
  description?: string | null
  rights: Right[]
}

export type Program = {
  id: string
  name: string
}

/** The node's facility comes as a reference only; its name is in the facilities lookup. */
export type SupervisoryNode = {
  id: string
  name: string
  facility?: { id: string } | null
}

export type Facility = {
  id: string
  code: string
  name: string
}

/** A role granted to a user; which ids are set depends on the role's type. */
export type RoleAssignment = {
  roleId: string
  programId?: string | null
  supervisoryNodeId?: string | null
  warehouseId?: string | null
}

/** The tabs of the roles page, one per role type, in the order OpenLMIS shows them. */
export const ROLE_TABS = [
  { id: "supervision", type: "SUPERVISION", label: "Supervision" },
  { id: "fulfillment", type: "ORDER_FULFILLMENT", label: "Fulfillment" },
  { id: "reports", type: "REPORTS", label: "Reports" },
  { id: "administration", type: "GENERAL_ADMIN", label: "Administration" },
] as const satisfies readonly { id: string; type: RightType; label: string }[]

export type RoleTab = (typeof ROLE_TABS)[number]

/** A supervision role with no supervisory node applies at the user's home facility. */
export function isHomeFacilityRole(assignment: RoleAssignment) {
  return Boolean(assignment.programId) && !assignment.supervisoryNodeId
}

/** Equal for two assignments that grant the same thing; the server keeps only one of them. */
export function assignmentKey(assignment: RoleAssignment) {
  const { roleId, programId, supervisoryNodeId, warehouseId } = assignment
  return [
    roleId,
    programId ?? "",
    supervisoryNodeId ?? "",
    warehouseId ?? "",
  ].join("|")
}

/** Only the ids the API reads, with empty ones left out. */
export function toSavedAssignment({
  roleId,
  programId,
  supervisoryNodeId,
  warehouseId,
}: RoleAssignment): RoleAssignment {
  return {
    roleId,
    ...(programId && { programId }),
    ...(supervisoryNodeId && { supervisoryNodeId }),
    ...(warehouseId && { warehouseId }),
  }
}

export const roleTypeOf = (role: Role | undefined): RightType | undefined =>
  role?.rights[0]?.type

/** The type an assignment belongs to: its role's, or what its ids imply if the role is gone. */
export function assignmentType(
  assignment: RoleAssignment,
  roles: ReadonlyMap<string, Role>
): RightType {
  const type = roleTypeOf(roles.get(assignment.roleId))
  if (type) return type
  if (assignment.programId) return "SUPERVISION"
  if (assignment.warehouseId) return "ORDER_FULFILLMENT"
  return "GENERAL_ADMIN"
}

/** Adds the assignments not held yet, keeping the current order, and counts both kinds. */
export function mergeAssignments(
  current: readonly RoleAssignment[],
  incoming: readonly RoleAssignment[]
) {
  const keys = new Set(current.map(assignmentKey))
  const added: RoleAssignment[] = []
  for (const assignment of incoming) {
    const key = assignmentKey(assignment)
    if (keys.has(key)) continue
    keys.add(key)
    added.push(toSavedAssignment(assignment))
  }
  return {
    assignments: [...current, ...added],
    added: added.length,
    skipped: incoming.length - added.length,
  }
}

/** How many assignments were added and removed since `saved`; zero when nothing changed. */
export function countChanges(
  saved: readonly RoleAssignment[],
  draft: readonly RoleAssignment[]
) {
  const savedKeys = new Set(saved.map(assignmentKey))
  const draftKeys = new Set(draft.map(assignmentKey))
  const added = [...draftKeys].filter((key) => !savedKeys.has(key)).length
  const removed = [...savedKeys].filter((key) => !draftKeys.has(key)).length
  return added + removed
}

export function countByType(
  assignments: readonly RoleAssignment[],
  roles: ReadonlyMap<string, Role>
) {
  const counts: Record<RightType, number> = {
    SUPERVISION: 0,
    ORDER_FULFILLMENT: 0,
    REPORTS: 0,
    GENERAL_ADMIN: 0,
  }
  for (const assignment of assignments)
    counts[assignmentType(assignment, roles)] += 1
  return counts
}

export type RoleLookups = {
  roles: ReadonlyMap<string, Role>
  programs: ReadonlyMap<string, Program>
  /** Missing while the nodes still load. */
  nodes?: ReadonlyMap<string, SupervisoryNode> | undefined
  /** Missing while the facilities still load. */
  facilities?: ReadonlyMap<string, Facility> | undefined
}

export const byId = <T extends { id: string }>(items: readonly T[]) =>
  new Map(items.map((item) => [item.id, item]))

/** One row of a roles tab; a name is undefined when its record is unknown or still loading. */
export type RoleRow = {
  id: string
  assignment: RoleAssignment
  role: string | undefined
  /** The role's description, shown with its rights. */
  description: string | undefined
  /** What the role grants, as labels. */
  rights: string[]
  program: string | undefined
  /** The supervisory node, or for a home facility role, the home facility. */
  node: string | undefined
  nodeFacility: string | undefined
  facility: string | undefined
  isHomeFacility: boolean
  /** A home facility role for a user with no home facility grants nothing. */
  isIgnored: boolean
  isUnsaved: boolean
}

type RowContext = {
  lookups: RoleLookups
  savedKeys: ReadonlySet<string>
  homeFacilityId: string | null | undefined
}

function toRoleRow(
  assignment: RoleAssignment,
  { lookups, savedKeys, homeFacilityId }: RowContext
): RoleRow {
  const key = assignmentKey(assignment)
  const role = lookups.roles.get(assignment.roleId)
  const isHomeFacility = isHomeFacilityRole(assignment)
  const node = assignment.supervisoryNodeId
    ? lookups.nodes?.get(assignment.supervisoryNodeId)
    : undefined
  const facilityName = (id: string | null | undefined) =>
    id ? lookups.facilities?.get(id)?.name : undefined

  return {
    id: key,
    assignment,
    role: role?.name,
    description: role?.description ?? undefined,
    rights: (role?.rights ?? []).map((right) => rightLabel(right.name)),
    program: assignment.programId
      ? lookups.programs.get(assignment.programId)?.name
      : undefined,
    node: node?.name,
    nodeFacility: isHomeFacility
      ? facilityName(homeFacilityId)
      : facilityName(node?.facility?.id),
    facility: facilityName(assignment.warehouseId),
    isHomeFacility,
    isIgnored: isHomeFacility && !homeFacilityId,
    isUnsaved: !savedKeys.has(key),
  }
}

/** The rows of one tab, by role, then program, then node. */
export function toRoleRows(
  assignments: readonly RoleAssignment[],
  type: RightType,
  context: RowContext
): RoleRow[] {
  const rows = assignments
    .filter(
      (assignment) => assignmentType(assignment, context.lookups.roles) === type
    )
    .map((assignment) => toRoleRow(assignment, context))
  // oxlint-disable-next-line unicorn/no-array-sort -- sorts a fresh array; toSorted needs the ES2023 lib
  return rows.sort(compareRows("role", false))
}

export const ROLE_SORT_FIELDS = ["role", "program", "node", "facility"] as const

export type RoleSortField = (typeof ROLE_SORT_FIELDS)[number]

// Ties fall through to the next field, so equal roles still list in a steady order.
const SORT_ORDER: Record<RoleSortField, RoleSortField[]> = {
  role: ["role", "program", "node", "facility"],
  program: ["program", "role", "node"],
  node: ["node", "role", "program"],
  facility: ["facility", "role"],
}

const collator = new Intl.Collator(undefined, {
  sensitivity: "base",
  numeric: true,
})

export function compareRows(field: RoleSortField, desc: boolean) {
  return (a: RoleRow, b: RoleRow) => {
    for (const key of SORT_ORDER[field]) {
      const order = collator.compare(a[key] ?? "", b[key] ?? "")
      if (order !== 0) return key === field && desc ? -order : order
    }
    return 0
  }
}

/** Lower case without accents, so "deposito" finds "Depósito". */
const fold = (text: string) =>
  text.normalize("NFD").replace(/\p{M}/gu, "").toLocaleLowerCase()

/** Rows where any shown name contains `query`, ignoring case and accents. */
export function filterRows(rows: readonly RoleRow[], query: string) {
  const term = fold(query.trim())
  if (!term) return [...rows]
  const matches = (value: string | undefined) =>
    value !== undefined && fold(value).includes(term)
  return rows.filter((row) =>
    [row.role, row.program, row.node, row.nodeFacility, row.facility].some(
      matches
    )
  )
}

// Kept as written rather than capitalized like a word.
const ACRONYMS: Record<string, string> = {
  BUQ: "BUQ",
  CCE: "CCE",
  DHIS2: "DHIS2",
  MOH: "MOH",
  PODS: "PODs",
  PORALG: "PORALG",
}

/** A right's code as words, e.g. `PODS_MANAGE` as "PODs Manage"; swap in your own labels. */
export function rightLabel(name: string) {
  return name
    .split("_")
    .filter(Boolean)
    .map(
      (word) => ACRONYMS[word] ?? word.charAt(0) + word.slice(1).toLowerCase()
    )
    .join(" ")
}

